/** Stream all items (async-enumerable) */
export function useListItemsStream(query?: { filter?: string }, options?: { enabled?: boolean }) {
  const api = useApiService();
  const [items, setItems] = useState<readonly Item[]>([]);
  const [status, setStatus] = useState<'idle' | 'streaming' | 'success' | 'error'>('idle');
  const [error, setError] = useState<Error | null>(null);
  const controllerRef = useRef<AbortController | null>(null);

  const cancel = useCallback(() => {
    controllerRef.current?.abort();
    controllerRef.current = null;
    setStatus('idle');
  }, []);

  const reset = useCallback(() => {
    cancel();
    setItems([]);
    setError(null);
  }, [cancel]);

  const enabled = options?.enabled !== false;
  const keyDep = JSON.stringify({ query });

  useEffect(() => {
    if (!enabled) return;

    const controller = new AbortController();
    controllerRef.current = controller;
    setStatus('streaming');
    setItems([]);
    setError(null);

    let buffer: Item[] = [];
    let flushTimer: ReturnType<typeof setTimeout> | null = null;
    const flush = () => { flushTimer = null; if (!controller.signal.aborted) setItems(buffer.slice()); };
    (async () => {
      try {
        for await (const item of api.items.listItems(query, controller.signal)) {
          if (controller.signal.aborted) return;
          buffer.push(item);
          if (flushTimer === null) flushTimer = setTimeout(flush, 200);
        }
        if (!controller.signal.aborted) {
          if (flushTimer !== null) clearTimeout(flushTimer);
          setItems(buffer.slice());
          setStatus('success');
        }
      } catch (err) {
        if (controller.signal.aborted) return;
        if (err instanceof DOMException && err.name === 'AbortError') return;
        if (flushTimer !== null) clearTimeout(flushTimer);
        setItems(buffer.slice());
        setError(err as Error);
        setStatus('error');
      }
    })();

    return () => { controller.abort(); if (flushTimer !== null) clearTimeout(flushTimer); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, keyDep]);

  return { items, status, error, cancel, reset };
}

